import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Operations and upgrades","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operations.md","filePath":"guide/operations.md"}'),n={name:"guide/operations.md"};function r(l,e,o,d,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="operations-and-upgrades" tabindex="-1">Operations and upgrades <a class="header-anchor" href="#operations-and-upgrades" aria-label="Permalink to &quot;Operations and upgrades&quot;">​</a></h1><h2 id="run-as-a-service" tabindex="-1">Run as a service <a class="header-anchor" href="#run-as-a-service" aria-label="Permalink to &quot;Run as a service&quot;">​</a></h2><p>Review the generated service definition, then install it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>The default is a systemd user service. Install prompts for confirmation and starts the service. If it must survive logout, enable lingering for its operating-system user with <code>loginctl enable-linger USERNAME</code>. PM2 and system-scope systemd are also supported.</p><p><code>gateway restart</code> drives the currently active owner. <code>service start</code> and <code>service restart</code> can find an installed but stopped service. Start/restart exit code <code>2</code> means the action succeeded but health could not be confirmed; inspect logs before treating it as healthy.</p><h2 id="observe-the-running-system" tabindex="-1">Observe the running system <a class="header-anchor" href="#observe-the-running-system" aria-label="Permalink to &quot;Observe the running system&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lines</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --follow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Use <code>/dashboard</code> for sessions and knowledge views. Log in with an admin key. Keep <code>/health</code> checks alongside a real agent round trip: a responsive HTTP listener does not prove a channel or model works.</p><h2 id="upgrade-deliberately" tabindex="-1">Upgrade deliberately <a class="header-anchor" href="#upgrade-deliberately" aria-label="Permalink to &quot;Upgrade deliberately&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Review release changes and back up configuration, agent workspaces/session data, and relevant app data before upgrading. Store backups securely because configuration contains credentials. Stop or coordinate active work before restarting.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>The update command confirms before replacing the installed package. The running process continues using its previous build until restarted. Afterward, check the version and send a test message over each important channel.</p><p>For Claude Code itself, use <code>claude-gateway claude update check</code> and <code>claude-gateway claude update</code>; it uses Claude Code&#39;s native updater. Older service units that invoke the binary without a command should be updated to explicit <code>gateway start</code>.</p><h2 id="preserve-a-recovery-path" tabindex="-1">Preserve a recovery path <a class="header-anchor" href="#preserve-a-recovery-path" aria-label="Permalink to &quot;Preserve a recovery path&quot;">​</a></h2><p>Keep the previous package version and a matching backup recorded. A rollback must consider configuration migration and runtime data as well as package files. Avoid changing branches or rebuilding a source deployment while it is serving traffic. Work in an independent checkout, then deploy a consistent revision.</p><p>See <a href="./troubleshooting.html">troubleshooting</a> for targeted failure diagnosis.</p><h2 id="choose-a-process-owner" tabindex="-1">Choose a process owner <a class="header-anchor" href="#choose-a-process-owner" aria-label="Permalink to &quot;Choose a process owner&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Suitable use</th><th>Operational detail</th></tr></thead><tbody><tr><td>Foreground <code>gateway start</code></td><td>Development or supervision by another process manager</td><td>Terminal/process owner controls lifetime</td></tr><tr><td>systemd user service</td><td>One user&#39;s normal deployment</td><td>Default service install; lingering may be needed after logout</td></tr><tr><td>systemd system service</td><td>Machine-managed deployment under a dedicated user</td><td>Requires explicit <code>--scope system --run-as USERNAME</code></td></tr><tr><td>PM2</td><td>Existing PM2-managed environments</td><td>Select with <code>--manager pm2</code>; system scope is not supported</td></tr></tbody></table><p>Preview an alternative service definition before installing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run-as</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pm2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print</span></span></code></pre></div><p>Replace <code>gateway</code> with an existing operating-system account. For a system service, ensure that account can read the intended configuration and workspace and run the provider executable. A root shell&#39;s home and credentials are not the service account&#39;s home and credentials.</p><p>The installer checks for an enabled or active unit at the opposite systemd scope and refuses to create a competing owner. If it reports a conflict, inspect both scopes and decide which should own the gateway before installing. Two independent processes can compete for the HTTP port or channel polling even if their service names look similar.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/cli/commands/service.ts" target="_blank" rel="noreferrer">service command and unit rendering</a>.</p><h2 id="separate-process-health-from-end-to-end-health" tabindex="-1">Separate process health from end-to-end health <a class="header-anchor" href="#separate-process-health-from-end-to-end-health" aria-label="Permalink to &quot;Separate process health from end-to-end health&quot;">​</a></h2><p>Use service status to determine whether the supervisor believes the process is running. Use gateway status and <code>/health</code> to determine whether the intended gateway responds. Use one real agent message to check authentication, executable discovery, workspace loading, and model response. Finally, test the channel or app path used by people.</p><p>When a start/restart returns exit code <code>2</code>, the owner action completed but health verification did not establish readiness. Inspect startup logs and the configured address before retrying: immediately starting another process can turn a slow startup into a duplicate-owner problem.</p><p>An interactive shell may have a different <code>PATH</code> and environment from a service. If <code>claude</code> or Bun works in a terminal but fails under supervision, inspect the service definition and run-as account. The gateway includes native Claude binary discovery, but a missing installation or authentication under the service account still needs to be fixed.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/cli/commands/gateway.ts" target="_blank" rel="noreferrer">gateway lifecycle command</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/cli/health.ts" target="_blank" rel="noreferrer">health checks</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/session/claude-bin.ts" target="_blank" rel="noreferrer">Claude executable discovery</a>.</p><h2 id="back-up-by-data-responsibility" tabindex="-1">Back up by data responsibility <a class="header-anchor" href="#back-up-by-data-responsibility" aria-label="Permalink to &quot;Back up by data responsibility&quot;">​</a></h2><p>Preserve the effective config file and referenced credentials, agent workspace source files, session persistence, history databases, personal/shared knowledge sources, and managed cron storage. For container apps, use the app backup flow to capture data that lives in Docker volumes; copying only the gateway directory is not sufficient for those volumes.</p><p>Record the gateway package version and provider version alongside the backup. After recovery or upgrade, check selected agent/session, personal and shared retrieval, enabled schedules, restored apps, and each important channel. A successful package install does not verify these persisted-data paths.</p>`,33)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
